#!/usr/bin/env node
/**
 * Build the claude.ai/design "styles-only" bundle for rcsd.info.
 *
 * rcsd.info has no component library (vanilla HTML/CSS emitted by Node
 * builders), so this sync ships the site's visual identity — design tokens,
 * self-hosted fonts, base styles, and curated recurring CSS patterns — plus
 * hand-authored foundation preview cards, so Claude Design produces
 * rcsd.info-branded designs with generic components.
 *
 * Sources (live, never copied by hand):
 *   - tokens + base/nav/footer CSS: baseCSS() from ../scripts/html-parts.mjs
 *   - fonts: ../docs/fonts/ (fonts.css + woff2, relative url()s preserved)
 * Curated (hand-maintained, with provenance headers):
 *   - patterns.css: recurring page-level patterns (hero, cards, badges,
 *     section heads) copied from scripts/build-homepage.mjs — see its header
 *   - cards/*.html: foundation preview cards (Colors, Typography, Patterns)
 *   - ../README-header.md (conventions.md): conventions guide for the agent
 *
 * Output: .design-sync/ds-bundle/ (gitignored). Idempotent; safe to re-run.
 */
import { mkdirSync, readFileSync, writeFileSync, copyFileSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { baseCSS } from '../scripts/html-parts.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, '..');
const out = join(here, 'ds-bundle');

rmSync(out, { recursive: true, force: true });
mkdirSync(join(out, 'tokens'), { recursive: true });
mkdirSync(join(out, 'fonts'), { recursive: true });

// ---- split baseCSS into tokens (:root block) and base styles ----
const css = baseCSS();
const rootMatch = css.match(/:root\s*\{[\s\S]*?\n\s*\}/);
if (!rootMatch) throw new Error('could not find :root token block in baseCSS()');
const tokens = rootMatch[0];
const base = css.replace(rootMatch[0], '').trim();

writeFileSync(join(out, 'tokens', 'colors.css'),
  `/* rcsd.info design tokens — extracted live from scripts/html-parts.mjs baseCSS() */\n${tokens}\n`);

// ---- fonts: copy as-is (fonts.css uses relative url()s next to the woff2s) ----
for (const f of readdirSync(join(repo, 'docs', 'fonts'))) {
  copyFileSync(join(repo, 'docs', 'fonts', f), join(out, 'fonts', f));
}

// ---- curated patterns layer ----
const patterns = readFileSync(join(here, 'patterns.css'), 'utf8');
writeFileSync(join(out, 'patterns.css'), patterns);

// ---- styles.css: the @import closure every rendered design receives ----
writeFileSync(join(out, 'styles.css'), `/*
 * rcsd.info design system — styles-only bundle for claude.ai/design.
 * Generated by .design-sync/build-bundle.mjs; do not edit by hand.
 * Tokens + base come live from scripts/html-parts.mjs baseCSS();
 * patterns.css is curated from scripts/build-homepage.mjs (see its header).
 */
@import "fonts/fonts.css";
@import "tokens/colors.css";
@import "patterns.css";

${base}
`);

// ---- README: conventions header + generated inventory ----
const conventions = readFileSync(join(here, 'conventions.md'), 'utf8');
writeFileSync(join(out, 'README.md'), `${conventions}

---

## Bundle inventory (generated)

- \`styles.css\` — entry stylesheet; @imports fonts, tokens, and patterns, then the base/nav/footer styles.
- \`tokens/colors.css\` — the \`:root\` custom-property palette.
- \`fonts/\` — self-hosted Fraunces, Newsreader, IBM Plex Mono (woff2 + \`fonts.css\`).
- \`patterns.css\` — recurring page patterns: hero, section heads, cards, badges, event rows, data labels.
- \`components/foundations/\` — preview cards for the Design System pane (Colors, Typography, Patterns).

Source of truth: https://github.com/dweekly/rcsd-meetings — tokens/base CSS in \`scripts/html-parts.mjs\`, page patterns in \`scripts/build-homepage.mjs\`.
`);

// ---- foundation preview cards ----
for (const card of readdirSync(join(here, 'cards')).filter(f => f.endsWith('.html'))) {
  const name = card.replace(/\.html$/, '');
  const dir = join(out, 'components', 'foundations', name);
  mkdirSync(dir, { recursive: true });
  copyFileSync(join(here, 'cards', card), join(dir, card));
}

console.log('ds-bundle built at', out);
